            result.append((start, i))
            start = None
    return result

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_bands = [band for band in _runs([any(v != 0 for v in row) for row in grid]) if band[1] - band[0] >= 3]
    col_bands = [band for band in _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)]) if band[1] - band[0] >= 3]
    cells = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            r, c = (r0 + r1 - 1) // 2, (c0 + c1 - 1) // 2
            color = grid[r][c]
            if color:
                cells[(ri, ci)] = (r, c, color)
    # Join aligned occurrences of each center color, drawing only through blank gaps.
    for ri in range(len(row_bands)):
        by_color = {}
        for (ridx, cidx), (r, c, color) in cells.items():
