    for i, flag in enumerate(flags + [False]):
        if flag and start is None:
            start = i
        elif not flag and start is not None:
            result.append((start, i))
            start = None
    return result

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_bands = [b for b in _runs([any(v != 0 for v in row) for row in grid]) if b[1] - b[0] >= 3]
    col_bands = [b for b in _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)]) if b[1] - b[0] >= 3]
    cells = {}
    counts = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            r, c = (r0 + r1 - 1) // 2, (c0 + c1 - 1) // 2
            color = grid[r][c]
            if color:
                cells[(ri, ci)] = color
                counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    common = max(counts, key=counts.get)
    # Connect only the less common tile colors; preserve each tile's full inner thickness.
    for ri, (r0, r1) in enumerate(row_bands):
        for color in counts:
            if color == common:
                continue
            cols = [ci for ci in range(len(col_bands)) if cells.get((ri, ci)) == color]
            for ca, cb in zip(cols, cols[1:]):
                gap0, gap1 = col_bands[ca][1], col_bands[cb][0]
                for r in range(r0 + 1, r1 - 1):
                    for c in range(gap0, gap1):
                        if out[r][c] == 0:
                            out[r][c] = color
    for ci, (c0, c1) in enumerate(col_bands):
        for color in counts:
            if color == common:
                continue
            rows = [ri for ri in range(len(row_bands)) if cells.get((ri, ci)) == color]
            for ra, rb in zip(rows, rows[1:]):
                gap0, gap1 = row_bands[ra][1], row_bands[rb][0]
                for r in range(gap0, gap1):
                    for c in range(c0 + 1, c1 - 1):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
